(function () {
  var root = document.getElementById('shop');
  if (!root) return;
  var cards = Array.prototype.slice.call(root.querySelectorAll('.cat-card'));
  var groups = Array.prototype.slice.call(root.querySelectorAll('.cat-group'));
  var tabs = Array.prototype.slice.call(root.querySelectorAll('.cat-tab'));
  var empty = root.querySelector('#cat-empty');
  var state = { category: 'all' };

  function toProduct(el) {
    return {
      el: el,
      name: el.getAttribute('data-name'),
      category: el.getAttribute('data-category'),
      price: Number(el.getAttribute('data-price')),
      sizes: el.getAttribute('data-sizes').split(','),
      isNew: el.getAttribute('data-new') === 'true'
    };
  }

  var api = window.J2Catalogue = window.J2Catalogue || {};
  api.products = cards.map(toProduct);
  api.filter = api.filter || null; // other sections may set: function (product) { return true|false }
  api.getCategory = function () { return state.category; };

  function render() {
    var shown = 0;
    api.products.forEach(function (p) {
      var ok = state.category === 'all' || p.category === state.category;
      if (ok && typeof api.filter === 'function') {
        try { ok = api.filter(p) !== false; } catch (e) { ok = true; }
      }
      p.el.hidden = !ok;
      if (ok) shown++;
    });
    groups.forEach(function (g) {
      g.hidden = !g.querySelector('.cat-card:not([hidden])');
    });
    if (empty) empty.hidden = shown > 0;
    document.dispatchEvent(new CustomEvent('j2:catalogue-rendered', { detail: { shown: shown } }));
  }
  api.render = render;

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      state.category = tab.getAttribute('data-cat');
      tabs.forEach(function (t) {
        t.setAttribute('aria-pressed', t === tab ? 'true' : 'false');
      });
      render();
    });
  });

  render();
})();
</script>
